#!/usr/bin/env node
// Task 3's gate: the CANONICAL checker (tools/mesh_validate.py), run before and
// after on real pieces, with the before/after numbers compared by machine
// instead of by eye.
//
//   node tools/nso_extend_canonical_check.js      exit 0 = every gate held
//
// Depends on tools/nso_extend_test.js having written tools/extend-out/; it runs
// that first so the pair under test is always generated by the shipped code.
//
// WHAT IS ASSERTED, and why each one:
//
//   triangles, unique_edges, welded_vertices      Extend re-tessellates nothing.
//   open / nonmanifold / odd edges                A stretch cannot unseal a mesh.
//   inconsistent_winding, euler_characteristic    Topology is literally untouched.
//   degenerate_tris                               Stretching adds area, never removes it;
//                                                 a Shorten stays inside its band margin.
//   selfint pierce + coplanar                     Whatever the piece already had, it
//                                                 still has - no more, no fewer.
//   bbox on the two cross-section axes            THE promise. Exact equality.
//   bbox on the axis                              Exactly the requested length.
//   signed_volume                                 Grew (or, shortened, shrank) by
//                                                 cross-section x shift, to the
//                                                 checker's own precision.
//
// WHAT IS MEASURED BUT NOT GATED, because it legitimately moves:
//
//   sliver_tris / worst_aspect_ratio  A wall triangle stretched along the axis
//     keeps its cross-section width and gains length, so its aspect ratio rises
//     by construction. pin.stl goes 0 -> 64 slivers at the checker's aspect>100
//     threshold on a 20 -> 32 mm stretch. That is the shape of the answer, not a
//     defect: degenerate_tris stays 0, area grows, and the SHORTEST edge in the
//     mesh is a cross-section edge, so it is untouched - which is what the weld
//     tolerances in NSO_sculptWeldTol and NSO_weldEpsFor are keyed off. Extend
//     moves edge lengths in the safe direction for both of them.

const { execFileSync } = require('child_process');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'tools', 'extend-out');

let pass = 0, fail = 0;
const FAILS = [];
function check(name, cond, detail) {
  if (cond) { pass++; console.log('  ok    ' + name + (detail ? '   ' + detail : '')); }
  else { fail++; FAILS.push(name); console.log('  FAIL  ' + name + (detail ? '   ' + detail : '')); }
}

console.log('== regenerating tools/extend-out/ from the shipped code ==');
execFileSync(process.execPath, [path.join(ROOT, 'tools', 'nso_extend_test.js')], { stdio: 'ignore' });

const validate = f => JSON.parse(execFileSync('python3',
  [path.join(ROOT, 'tools', 'mesh_validate.py'), path.join(OUT, f + '.stl'), '--json'],
  { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 }));

// name, before, after, axis index, target length, geometric cross-section mm^2
const CASES = [
  ['lid_strap  60 -> 95 mm span (living-hinge flexure)',
   // one closed shell since fixtures 6e0182e: 96 lid + 6 strap - 1.2 overlap
   'lid_strap_60', 'lid_strap_95', 0, 95, 40 * 2.4 + 10 * 0.6 - 2 * 0.6],
  ['hinge_knuckle_box  18 -> 26 mm barrel',
   'hinge_knuckle_box_18', 'hinge_knuckle_box_26', 0, 26, null],
  ['pin  20 -> 32 mm shaft (chamfers at both ends)',
   'pin_20', 'pin_32', 0, 32, Math.PI * 1.5 * 1.5],
  // Shorten: the same three pieces, the other way, inside one band each.
  ['lid_strap  60 -> 25 mm (Shorten)',
   'lid_strap_60', 'lid_strap_25', 0, 25, 40 * 2.4 + 10 * 0.6 - 2 * 0.6],
  ['hinge_knuckle_box  18 -> 16 mm (Shorten, inside the 3.6 mm finger band)',
   'hinge_knuckle_box_18', 'hinge_knuckle_box_16', 0, 16, null],
  ['pin  20 -> 10 mm (Shorten, chamfers at both ends)',
   'pin_20', 'pin_10', 0, 10, Math.PI * 1.5 * 1.5],
];

const EXACT = ['triangles', 'welded_vertices', 'unique_edges', 'open_edges',
  'nonmanifold_edges', 'odd_edges', 'inconsistent_winding_edges',
  'euler_characteristic', 'degenerate_tris'];

for (const [title, bName, aName, axis, target, xsec] of CASES) {
  console.log('\n== ' + title + ' ==');
  const b = validate(bName), a = validate(aName);
  console.log('   before  ' + EXACT.map(k => k.split('_')[0] + ' ' + b[k]).join('  '));
  console.log('   after   ' + EXACT.map(k => k.split('_')[0] + ' ' + a[k]).join('  '));
  for (const k of EXACT) check(k + ' unchanged', a[k] === b[k], b[k] + ' -> ' + a[k]);

  check('self-intersecting pierce pairs unchanged',
    a.self_intersection.pierce === b.self_intersection.pierce,
    b.self_intersection.pierce + ' -> ' + a.self_intersection.pierce);
  check('coplanar overlap pairs unchanged',
    a.self_intersection.coplanar === b.self_intersection.coplanar,
    b.self_intersection.coplanar + ' -> ' + a.self_intersection.coplanar);

  const cross = [0, 1, 2].filter(i => i !== axis);
  for (const c of cross) {
    check('bbox ' + 'XYZ'[c] + ' (cross-section) EXACTLY unchanged',
      a.bbox_size[c] === b.bbox_size[c] && a.bbox_min[c] === b.bbox_min[c] &&
      a.bbox_max[c] === b.bbox_max[c],
      b.bbox_min[c] + '..' + b.bbox_max[c] + '  ->  ' + a.bbox_min[c] + '..' + a.bbox_max[c]);
  }
  check('bbox ' + 'XYZ'[axis] + ' is the requested length', a.bbox_size[axis] === target,
    b.bbox_size[axis] + ' -> ' + a.bbox_size[axis] + ' mm');
  check('the fixed end did not move', a.bbox_min[axis] === b.bbox_min[axis]);

  const dV = a.signed_volume - b.signed_volume;
  const dL = a.bbox_size[axis] - b.bbox_size[axis];
  const implied = dV / dL;
  check(dL > 0 ? 'volume grew' : 'volume shrank', dL > 0 ? dV > 0 : dV < 0,
    dV.toFixed(4) + ' mm^3 over ' + dL + ' mm');
  if (xsec != null) {
    check('added volume / added length = the cut cross-section',
      Math.abs(implied - xsec) / xsec < (xsec > 50 ? 1e-5 : 0.01),
      implied.toFixed(5) + ' mm^2 vs geometric ' + xsec.toFixed(5) + ' mm^2');
  } else {
    console.log('   implied cross-section ' + implied.toFixed(5) + ' mm^2');
  }
  console.log('   NOT GATED: sliver_tris ' + b.sliver_tris + ' -> ' + a.sliver_tris +
    ', worst aspect ' + b.worst_aspect_ratio.toFixed(3) + ' -> ' + a.worst_aspect_ratio.toFixed(3) +
    '   (wall triangles get ' + (dL > 0 ? 'longer' : 'shorter') + '; degenerate stays ' + a.degenerate_tris + ')');
}

console.log('\n' + pass + ' passed, ' + fail + ' failed');
if (fail) { console.log('failing:'); for (const f of FAILS) console.log('  - ' + f); }
process.exit(fail === 0 ? 0 : 1);
